const defaultEvents = (state, entity_type) => ({
  curator: async (entity_id, field, value) => await state.curator(entity_type, entity_id, field, value),
  owner: async (entity_id, field, value) => await state.owner(entity_type, entity_id, field, value)
});
const useEntityApi = defineStore("entity-api", {
  state: () => ({
    default: {
      ARTIST: {
        curator: {
          MAX_TRACK_CREATE_COUNT: 80
        }
      }
    }
  }),
  getters: {
    artist: (state) => defaultEvents(state, "ARTIST"),
    release: (state) => defaultEvents(state, "RELEASE"),
    track: (state) => defaultEvents(state, "TRACK"),
    playlist: (state) => defaultEvents(state, "PLAYLIST")
  },
  actions: {
    getEntityCode(item) {
      const entityObj = {
        artists: "ARTIST",
        releases: "RELEASE",
        tracks: "TRACK",
        playlist: "PLAYLIST"
      };
      return entityObj[item] || item;
    },
    async curator(entity_type, entity_id, field, value) {
      const entity = this.getEntityCode(entity_type);
      let curatorSettings = { ...this.default[entity]?.curator || {} };
      try {
        const result = await this.$http({
          method: "GET",
          url: `/entity-settings/curator/${entity}/${entity_id}`
          // signal: requests.signal('entity-curator-get')
        });
        if (result.status === 200) {
          const { data } = result;
          curatorSettings = { ...curatorSettings, ...data?.curatorSettings || {} };
        }
      } catch (e) {
        onRequestDefaultError(e);
      }
      if (value === void 0) {
        if (field === void 0) {
          return curatorSettings;
        }
        return curatorSettings ? curatorSettings[field] : void 0;
      }
      curatorSettings[field] = value;
      try {
        const result = await this.$http({
          method: "PUT",
          url: `/entity-settings/curator/${entity}/${entity_id}`,
          data: curatorSettings
          // signal: requests.signal('entity-curator-set')
        });
        if (result.status === 200) {
          const { data } = result;
          return data;
        }
      } catch (e) {
        onRequestDefaultError(e);
      }
    },
    async owner(entity_type, entity_id, field, value) {
      const entity = this.getEntityCode(entity_type);
      let ownerSettings = { ...this.default[entity]?.owner || {} };
      try {
        const result = await this.$http({
          method: "GET",
          url: `/entity-settings/owner/${entity}/${entity_id}`
          // signal: requests.signal('entity-owner-get')
        });
        if (result.status === 200) {
          const { data } = result;
          ownerSettings = { ...ownerSettings, ...data?.ownerSettings || {} };
        }
      } catch (e) {
        onRequestDefaultError(e);
      }
      if (value === void 0) {
        if (field === void 0) {
          return ownerSettings;
        }
        return ownerSettings ? ownerSettings[field] : void 0;
      }
      ownerSettings[field] = value;
      try {
        const result = await this.$http({
          method: "PUT",
          url: `/entity-settings/owner/${entity}/${entity_id}`,
          data: ownerSettings
          // signal: requests.signal('entity-owner-set')
        });
        if (result.status === 200) {
          const { data } = result;
          return data;
        }
      } catch (e) {
        onRequestDefaultError(e);
      }
    }
  }
});

const useTgsApi = defineStore("tgs-api", {
  state: () => ({
    collections: [],
    collection: {}
  }),
  actions: {
    async getCollections() {
      if (this.collections?.length) {
        return this.collections;
      }
      try {
        const response = await fetch(`${undefined                                }/index.json`);
        if (!response.ok) {
          throw new Error(response.status);
        }
        const result = await response.json();
        if (result?.length) {
          this.collections = result;
          return result;
        }
        return [];
      } catch (e) {
      }
    },
    async getCollection(code) {
      if (this.collection[code]) {
        return this.collection[code];
      }
      try {
        const response = await fetch(`${undefined                                }/${code}/index.json`);
        if (!response.ok) {
          throw new Error(response.status);
        }
        const result = await response.json();
        if (result?.length) {
          this.collection[code] = result;
          return result;
        }
        return [];
      } catch (e) {
      }
    }
  }
});

